# AI use: Generated by Claude, Reviewed & Approved by Me
"""US7: vendors confirm pickups by code and see no-shows."""

from datetime import datetime
from zoneinfo import ZoneInfo

from flask import Blueprint, abort, flash, redirect, render_template, request, url_for
from flask_login import current_user, login_required
from sqlalchemy import select, update
from sqlalchemy.orm import selectinload

from .extensions import db
from .models import Listing, Reservation, ReservationStatus

pickups_bp = Blueprint("pickups", __name__)


def _now():
    return datetime.now(ZoneInfo("America/Denver")).replace(tzinfo=None)


def mark_no_shows(vendor_id=None):
    """AC 3: active reservations on ended listings become no-shows."""
    ended = select(Listing.id).where(Listing.pickup_end <= _now())
    if vendor_id is not None:
        ended = ended.where(Listing.vendor_id == vendor_id)
    db.session.execute(
        update(Reservation)
        .where(
            Reservation.status == ReservationStatus.ACTIVE,
            Reservation.listing_id.in_(ended),
        )
        .values(status=ReservationStatus.NO_SHOW)
    )


def confirm_pickup(code, vendor_id):
    """AC 1-2: mark a reservation picked up, or say why not.

    Returns (reservation, None) or (None, message). The caller commits or rolls back.
    """
    if not code:
        return None, "Enter a pickup code."
    reservation = db.session.scalar(
        select(Reservation)
        .where(Reservation.pickup_code == code)
        .with_for_update()
    )
    if reservation is None:
        return None, f"No reservation matches code {code}."
    listing = reservation.listing
    if listing.vendor_id != vendor_id:
        return None, "That code isn't for one of your listings."
    if reservation.status == ReservationStatus.PICKED_UP:
        return None, "This reservation was already picked up."
    if reservation.status == ReservationStatus.CANCELLED:
        return None, "This reservation was cancelled."
    now = _now()
    if reservation.status == ReservationStatus.NO_SHOW or listing.pickup_end <= now:
        return None, "The pickup window for this listing has ended."
    if listing.pickup_start > now:
        return None, "The pickup window for this listing hasn't started yet."
    reservation.status = ReservationStatus.PICKED_UP
    return reservation, None


@pickups_bp.route("/pickups", methods=["GET", "POST"])
@login_required
def pickups():
    if current_user.role != "vendor":
        abort(403, description="Only vendors can confirm pickups.")

    status = 200
    if request.method == "POST":
        code = request.form.get("code", "").strip().upper()
        reservation, error = confirm_pickup(code, current_user.id)
        if error:
            db.session.rollback()
            flash(error, "error")
            status = 400
        else:
            student, portions = reservation.student.username, reservation.portions
            db.session.commit()
            flash(f"Picked up: {student}, {portions} portion(s) to hand out.", "success")
            return redirect(url_for("pickups.pickups"))

    mark_no_shows(current_user.id)
    db.session.commit()
    listings = db.session.scalars(
        select(Listing)
        .where(Listing.vendor_id == current_user.id)
        .options(selectinload(Listing.reservations).selectinload(Reservation.student))
        .order_by(Listing.pickup_end.desc())
    ).all()
    return render_template("pickups.html", listings=listings), status
